let index: Map<string, number> | null = null;

function table() {
  if (!index) {
    index = new Map();
    for (const [inches, models] of Object.entries(BY_DIAGONAL)) {
      const value = Number(inches);
      for (const model of models.split("|")) index.set(model, value);
    }
  }
  return index;
}

/** Diagonal en pulgadas del modelo que reporta el teléfono, o `null` si no está en la tabla. */
export function diagonalInches(model: string): number | null {
  // El navegador de Samsung antepone la marca en su user agent («SAMSUNG SM-A546E»).
  const key = model.trim().toUpperCase().replace(/^SAMSUNG /, "");
  const exact = table().get(key);
  if (exact) return exact;
  // Samsung: la última letra es la región (SM-A546E, SM-A546B…); la pantalla es la misma.
  const samsung = /^SM-[A-Z]\d{3}/.exec(key);
  return (samsung && table().get(`${samsung[0]}*`)) || null;
}
